import{_ as i,o as a,c as e,a5 as t}from"./chunks/framework.BZzouRtU.js";const n="/study/images/threads/bounded-worker-queues.svg",u=JSON.parse('{"title":"C++の有界キューと条件変数","description":"","frontmatter":{"title":"C++の有界キューと条件変数","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"runtime","summary":"要求と結果の待ち行列に上限を設ける。条件変数で空きとデータを待ち、フレーム側で結果を回収してからワーカーを終了する。","aliases":["有界キュー","bounded queue","producer consumer","condition variable","std::condition_variable","std::unique_lock","notify_one","notify_all","backpressure","バックプレッシャー","close","drain"],"verification":"C++20草案N4861の条件変数・mutex・joinに照合（2026-11-06）"}},"headers":[],"relativePath":"runtime/bounded-worker-queues.md","filePath":"runtime/bounded-worker-queues.md"}'),r={name:"runtime/bounded-worker-queues.md"};function h(l,s,p,o,d,k){return a(),e("div",null,[...s[0]||(s[0]=[t('<h1 id="c-の有界キューと条件変数" tabindex="-1">C++の有界キューと条件変数 <a class="header-anchor" href="#c-の有界キューと条件変数" aria-label="Permalink to &quot;C++の有界キューと条件変数&quot;">​</a></h1><p>メッシュを読み込む処理では、要求を出す側、データを準備するワーカー、結果を受け取る描画側が、それぞれ違う速さで進みます。ワーカーが満杯のキューへ結果を入れようとすると、空きができるまで待ちます。要求側のキューも満杯になれば、要求を出す側まで待ちが伝わります。このように下流の空きに合わせて上流を調整することを<strong>バックプレッシャー</strong>と呼びます。<a href="/study/runtime/thread-synchronization.html">スレッドと同期</a> · <a href="/study/game/asset-worker-handoff.html">アセットを描画スレッドへ渡す</a></p><figure class="study-figure"><img src="'+n+`" alt="要求側が有界の要求キューへ投入し、二つのワーカーが処理した結果を有界の結果キューに入れる。結果キューが満杯になるとワーカーが空きを待つ。終了時は要求の受付を閉じ、フレーム側が結果を取り続け、ワーカーの終了と残りの結果を確認する。" width="760" height="430" loading="lazy"><figcaption>満杯になったキューでは投入側が空きを待ちます。終了中もフレーム側が結果を取り出せば、ワーカーは待ちを抜けて残りの処理を進められます。<a href="/study/images/threads/bounded-worker-queues.svg" target="_blank" rel="noopener noreferrer">キューと終了順の図を拡大</a></figcaption></figure><h2 id="ワーカー数とキューの容量を決める" tabindex="-1">ワーカー数とキューの容量を決める <a class="header-anchor" href="#ワーカー数とキューの容量を決める" aria-label="Permalink to &quot;ワーカー数とキューの容量を決める&quot;">​</a></h2><p>有界キューは同時に格納できる要素の数を制限する待ち行列です。例えば要求を2件まで、結果を1件までとし、ワーカーを2本置きます。キューから取り出した仕事はワーカーが保持します。二つのキューが満杯で各ワーカーが1件ずつ持つときは、待機中の要求2件、処理中または公開待ちの仕事2件、回収待ちの結果1件があります。キューへ投入しようとして待っている側が持つデータや回収済みのデータも、メモリの予算に含めます。</p><p>ワーカーを増やすと同時に担当できる仕事が増え、キューを広げると後で処理するために保持できる仕事が増えます。要素によってサイズが異なる場合は、件数とバイト数の両方に上限を設けると、大きなメッシュの結果が重なった場合も予算に収められます。満杯時の動作は受付の契約にします。例えばバックグラウンドの要求側は空きを待ち、フレーム内の要求側は満杯を受け取って後で再試行します。<a href="/study/game/asset-loading.html">アセットの依存関係と予算</a></p><h2 id="共有状態を調べてから条件変数で待つ" tabindex="-1">共有状態を調べてから条件変数で待つ <a class="header-anchor" href="#共有状態を調べてから条件変数で待つ" aria-label="Permalink to &quot;共有状態を調べてから条件変数で待つ&quot;">​</a></h2><p>同じmutexでキュー本体と受付状態 <code>closed_</code> を守ります。投入側は空きができるか受付が閉じるまで、取出し側はデータが入るか受付が閉じるまで待ちます。例えば次のように、ロックを取得した上で待つ条件を渡します。</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// push: wait for a free slot, or for close to reject the push.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">std</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">unique_lock</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> lock</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mutex_</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">not_full_.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wait</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(lock, [</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] { </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> closed_ </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">||</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> queue_.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">size</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> capacity_; });</span></span></code></pre></div><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// pop: wait for an item, or for close to let an empty queue finish.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">std</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">unique_lock</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> lock</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mutex_</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">not_empty_.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wait</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(lock, [</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] { </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> closed_ </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">||</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> !</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">queue_.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">empty</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(); });</span></span></code></pre></div><p>述語が偽なら、<code>wait</code>はmutexの解放と待機への移行を一体で行います。起きるとmutexを取り直し、述語を確認します。通知のあとに別のワーカーが先に要素を取ったり、通知なしで待機が解除されたりする場合があるので、ロックを取り直した時点の状態で進めるか決めます。<a href="https://timsong-cpp.github.io/cppwp/n4861/thread.condition.condvar" target="_blank" rel="noreferrer">C++20草案の条件変数と述語付きwait</a></p><p>投入では受付が開いていれば要素を追加し、取り出しを待つ側に <code>notify_one()</code> で知らせます。取出しでは要素を移してキューから消し、空きを待つ側に <code>notify_one()</code> で知らせます。共有状態をロック中に更新したあと、ロックを解放して通知する形にできます。別スレッドへ結果を渡す順序は、更新した側の <code>unlock()</code> と同じmutexを取得する側の <code>lock()</code> がつなぎます。通知を受ける時点までに待ち始めていないスレッドも、あとでロックを取り、状態を調べて進めます。<a href="https://timsong-cpp.github.io/cppwp/n4861/thread.mutex.requirements.mutex" target="_blank" rel="noreferrer">C++20草案のmutexによる同期</a> · <a href="https://timsong-cpp.github.io/cppwp/n4861/thread.condition.condvar" target="_blank" rel="noreferrer">C++20草案の条件変数</a></p><h2 id="フレーム側は、受け取れる分だけ処理する" tabindex="-1">フレーム側は、受け取れる分だけ処理する <a class="header-anchor" href="#フレーム側は、受け取れる分だけ処理する" aria-label="Permalink to &quot;フレーム側は、受け取れる分だけ処理する&quot;">​</a></h2><p>キュー内で行うのは、空きやデータの有無の確認、要素の追加や移動です。ワーカーのデコードや、フレーム側の登録は、キューから取り出したあとにロックの外で進めます。処理中のデータの所有者を一つに決めておけば、次のスレッドへ移したあとに元の所有者が書き換える経路も避けられます。<a href="/study/runtime/thread-synchronization.html">スレッドと同期</a> · <a href="/study/game/asset-worker-handoff.html">アセットを描画スレッドへ渡す</a></p><p>例えばフレームの先頭で <code>try_pop</code> を1回呼びます。結果があれば1件だけ取り出し、空なら次の処理へ進みます。ここでの <code>try_pop</code> はデータが入るまで条件変数で待たない操作です。内部で通常のmutexを取る実装では、他スレッドがロックを持っている間は取得待ちがあり得ます。ロック取得も待たずに進みたい場合は、<code>try_lock()</code> が失敗したときの扱いを決めます。取得失敗はキューを調べて空だった場合と区別できます。<a href="https://timsong-cpp.github.io/cppwp/n4861/thread.mutex.requirements.mutex" target="_blank" rel="noreferrer">C++20草案のlockとtry_lock</a></p><h2 id="受付を閉じ、残りを回収して終了する" tabindex="-1">受付を閉じ、残りを回収して終了する <a class="header-anchor" href="#受付を閉じ、残りを回収して終了する" aria-label="Permalink to &quot;受付を閉じ、残りを回収して終了する&quot;">​</a></h2><p>この構成の <code>close()</code> は、新しい投入の受付を止め、すでに入っている要素は受け取れるようにする操作です。mutexを取って <code>closed_</code> を設定し、空きを待つ側とデータを待つ側の両方を <code>notify_all()</code> で起こします。投入側は閉じた状態を見て失敗を返し、取出し側は残りを受け取り、閉じていて空なら終了します。<a href="https://timsong-cpp.github.io/cppwp/n4861/thread.condition.condvar" target="_blank" rel="noreferrer">C++20草案のnotify_allとwait</a></p><ol><li>要求キューを閉じます。ワーカーは受付済みの要求を取り出し、結果を送ります。</li><li>フレーム側はその間も結果を回収します。最後の結果の投入が済んだら、結果キューも閉じます。終了の管理役を別に置き、全ワーカーの終了を確認してから結果キューを閉じる構成も取れます。</li><li>閉じた結果キューが空になり、各スレッドの <code>join()</code> が戻ってからキューを破棄します。結果のうち、画面切替などで現在の世代から外れたものは受け取った上で破棄できます。<a href="https://timsong-cpp.github.io/cppwp/n4861/thread.thread.member" target="_blank" rel="noreferrer">C++20草案のjoin</a> · <a href="/study/game/asset-worker-handoff.html">結果の採用と世代</a></li></ol><p>結果キューが満杯のまま、結果を取り出す唯一のスレッドが先にワーカーの <code>join()</code> を呼ぶと、取出し側はワーカーの終了を待ち、ワーカーは結果キューの空きを待ちます。互いに必要な処理が進まないので、終了を待つ前にフレーム側の回収を続けるようにします。<a href="/study/practice/threads/asset-worker-handoff-observation.html">要求と結果をキューで渡すC++実践</a></p>`,19)])])}const g=i(r,[["render",h]]);export{u as __pageData,g as default};
